<div class="modal-content ad-role-modal">
  <div class="modal-header"><button type="button" class="close" data-dismiss="modal" aria-hidden="true">×</button><h4 class="modal-title" id="ad-role-modal-title">NEW ROLE</h4></div>
  <div class="modal-body"><form id="ad-role-form"><input type="hidden" name="role_id" id="ad-role-id"><div id="ad-role-message"></div><div class="ad-wizard-grid two"><div class="ad-field"><label>Role name</label><input class="form-control" name="role_name" id="ad-role-name" required maxlength="100" placeholder="e.g. Store Manager"></div><div class="ad-field"><label>Access panel</label><select class="form-control" name="role_access_panel" id="ad-role-panel" required><option value="">Select panel</option><option value="1">Back End only</option><option value="2">Front End only</option><option value="3">Both panels</option></select></div><div class="ad-field" style="grid-column:1/-1"><label>Description</label><textarea class="form-control" name="role_description" id="ad-role-description" rows="3" maxlength="500" placeholder="Describe what this role is responsible for"></textarea></div><div class="ad-field"><label>Dashboard access</label><select class="form-control" name="access_dash" id="ad-role-dashboard"><option value="0">No dashboard access</option><option value="1">Dashboard access</option></select></div><div class="ad-field"><label>Front-end permissions</label><input class="form-control" name="front_perm" id="ad-role-front" placeholder="e.g. sales,orders,customers"><small class="help-block">Use comma-separated permission codes or the existing permission format.</small></div></div></form></div>
  <div class="modal-footer"><button type="button" class="btn btn-sm btn-danger" data-dismiss="modal">CLOSE MODAL</button><button type="button" class="btn btn-sm btn-success" id="ad-save-role">SAVE ROLE</button></div>
</div>
